        if(pushed) continue;
        int minDist=t+1;
        for(auto i:adj[u]){
            if(edges[i].w && minDist>dist[edges[i].v]){
                minDist=dist[edges[i].v];
                arc[u]=i;
            }
        }
        gap[dist[u]]--;
        if(gap[dist[u]]==0) break;
        dist[u]=minDist+1;
        gap[dist[u]]++;
        u=pre[u];
    }
    return totalFlow;
}

