import java.util.*;
import java.io.*;

public class Main {
    static class Edge {
        int v, w;
        Edge(int v, int w) {
            this.v = v;
            this.w = w;
        }
    }

    static final int INF = 10000000;
    static final int N = 210;
    static final int M = 21000;

    static List<Integer>[] adj = new ArrayList[N];
    static Edge[] edges = new Edge[M];
    static int[] head = new int[N];
    static int edge_idx = 0;

    static int S, T;
    static int[] dist = new int[N];
    static int[] q = new int[N * 2];
    static int[] arc = new int[N];
    static int[] gap = new int[N];
    static int[] inq = new int[N];
    static int[] pre = new int[N];

    static char[][] gridA = new char[12][12];
    static char[][] gridB = new char[12][12];
    static int[][] sci = new int[12][12];
    static int[][] ca = new int[12][12];
    static int[][][] stone = new int[62][12][12];
    static int[][][][][] dp = new int[62][12][12][12][12];
    static int[][] dir = {{-1,0},{1,0},{0,-1},{0,1}};
    static int n, t;

    static int[] vis = new int[12*12];

    public static void main(String[] args) throws IOException {
        for (int i=0; i<N; i++) {
            adj[i] = new ArrayList<>();
        }
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());

        for (int i=0; i<100000; i++) {
            int dummy=0; dummy++;
        }

        for (int i=1; i<=n; i++) {
            String line = br.readLine();
            for (int j=1; j<=n; j++) {
                gridA[i][j] = line.charAt(j-1);
            }
        }

        for (int i=1; i<=n; i++) {
            String line = br.readLine();
            for (int j=1; j<=n; j++) {
                gridB[i][j] = line.charAt(j-1);
            }
        }

        for (int i=0; i<M; i++) {
            edges[i] = new Edge(0,0);
        }

        for (int i=0; i<N; i++) {
            adj[i].clear();
        }

        addEdge = (u, v, w) -> {
            edges[edge_idx] = new Edge(v, w);
            adj[u].add(edge_idx++);
            edges[edge_idx] = new Edge(u, 0);
            adj[v].add(edge_idx++);
        };

        // Initialize gridA and gridB
        for (int i=1; i<=n; i++) {
            for (int j=1; j<=n; j++) {
                if (gridA[i][j] == 'Z') {
                    stone[0][i][j] = 2;
                } else if (gridA[i][j] == 'Y') {
                    stone[0][i][j] = 1;
                } else {
                    sci[i][j] = gridA[i][j] - '0';
                }
            }
        }

        for (int i=1; i<=n; i++) {
            for (int j=1; j<=n; j++) {
                if (gridB[i][j] >= '0' && gridB[i][j] <= '9') {
                    ca[i][j] = gridB[i][j] - '0';
                }
            }
        }

        expand();

        for (int i=1; i<=n; i++) {
            for (int j=1; j<=n; j++) {
                if (sci[i][j] != 0) {
                    Arrays.fill(vis, 0);
                    dfs(i, j, i, j, 0);
                }
            }
        }

        for (int k=1; k<=t; k++) {
            for (int x=1; x<=n; x++) {
                for (int y=1; y<=n; y++) {
                    for (int nx=1; nx<=n; nx++) {
                        for (int ny=1; ny<=n; ny++) {
                            dp[k][x][y][nx][ny] += dp[k-1][x][y][nx][ny];
                        }
                    }
                }
            }
        }

        S = 0;
        T = n * n * 2 + 1;

        for (int i=1; i<=n; i++) {
            for (int j=1; j<=n; j++) {
                addEdge.apply(S, (i - 1) * n + j, sci[i][j]);
            }
        }

        for (int i=1; i<=n; i++) {
            for (int j=1; j<=n; j++) {
                addEdge.apply(n * n + (i - 1) * n + j, T, ca[i][j]);
            }
        }

        for (int x=1; x<=n; x++) {
            for (int y=1; y<=n; y++) {
                for (int nx=1; nx<=n; nx++) {
                    for (int ny=1; ny<=n; ny++) {
                        if (sci[x][y] != 0 && ca[nx][ny] != 0) {
                            if (dp[t][x][y][nx][ny] != 0) {
                                addEdge.apply((x - 1) * n + y, n * n + (nx - 1) * n + ny, INF);
                            }
                        }
                    }
                }
            }
        }

        int ans = maxFlow(S, T);
        System.out.println(ans);
    }

    static interface EdgeAdder {
        void apply(int u, int v, int w);
    }

    static EdgeAdder addEdge;

    static void expand() {
        for (int k=1; k<=t; ++k) {
            for (int i=1; i<=n; ++i) {
                for (int j=1; j<=n; ++j) {
                    if (stone[k-1][i][j] == 1)
                        stone[k][i][j] = 1;
                    else if (stone[k-1][i][j] == 2)
                        stone[k][i][j] = 2;
                    else {
                        for (int z=0; z<4; ++z) {
                            int nx = i + dir[z][0], ny = j + dir[z][1];
                            if (nx >= 1 && nx <= n && ny >= 1 && ny <= n) {
                                if (stone[k-1][nx][ny] == 2)
                                    stone[k][i][j] = 2;
                            }
                        }
                    }
                }
            }
        }
    }

    static void dfs(int x, int y, int nowx, int nowy, int k) {
        vis[nowx * 12 + nowy] = 1;
        dp[k][x][y][nowx][nowy] = 1;
        if (k >= t || stone[k][nowx][nowy] != 0) return;
        for (int z=0; z<4; ++z) {
            int nx = nowx + dir[z][0], ny = nowy + dir[z][1];
            if (nx >= 1 && nx <= n && ny >= 1 && ny <= n && vis[nx * 12 + ny] == 0) {
                if (stone[k][nx][ny] != 0) continue;
                dfs(x, y, nx, ny, k+1);
            }
        }
    }

    static int maxFlow(int s, int t) {
        Arrays.fill(dist, 0);
        Arrays.fill(pre, -1);
        Arrays.fill(arc, -1);
        Arrays.fill(gap, 0);
        Arrays.fill(inq, 0);
        int front=0, rear=0;
        q[rear++]=t; inq[t]=1; gap[0]++;
        dist[t]=0;
        while(front<rear){
            int u=q[front++];
            for(int i:adj[u]){
                int v=edges[i].v;
                if(inq[v]==0){
                    q[rear++]=v;
                    inq[v]=1;
                    dist[v]=dist[u]+1;
                    gap[dist[v]]++;
                    arc[v]=i;
                }
            }
        }
        int totalFlow=0, low=INF, u=s;
        while(dist[s]<t){
            boolean pushed=false;
            for(int i=arc[u]; i!=-1; i=adj[u].get(i)){
                if(edges[i].w>0 && dist[edges[i].v]+1==dist[u]){
                    low=Math.min(low,edges[i].w);
                    pre[edges[i].v]=u;
                    u=edges[i].v;
                    if(u==t){
                        for(int v=t; v!=s; v=pre[v]){
                            int i2=arc[pre[v]];
                            edges[i2].w-=low;
                            edges[i2^1].w+=low;
                        }
                        totalFlow+=low;
                        low=INF;
                        u=s;
                    }
                    pushed=true;
                    break;
                }
            }
            if(pushed) continue;
            int minDist=t+1;
            for(int i:adj[u]){
                if(edges[i].w>0 && minDist>dist[edges[i].v]){
                    minDist=dist[edges[i].v];
                    arc[u]=i;
                }
            }
            gap[dist[u]]--;
            if(gap[dist[u]]==0) break;
            dist[u]=minDist+1;
            gap[dist[u]]++;
            u=pre[u];
        }
        return totalFlow;
    }
}
